#' Import Rigaku X-ray diffraction data
#'
#' @description
#' Imports X-ray diffraction (XRD) data files generated by Rigaku
#' instruments. The function recognizes \code{ASC}, \code{TXT},
#' \code{RAS}, and \code{RASX} file formats and returns either a plain
#' data frame or an \code{xrd} S3 object.
#'
#' @param filename Character string giving the full path to the XRD data
#'   file.
#' @param xrd Logical; if \code{TRUE}, the returned object is assigned
#'   class \code{"xrd"}.
#'
#' @details
#' The returned data contain at least the following columns:
#' \describe{
#'   \item{\code{TwoTheta}}{Diffraction angle (2theta, in degrees).}
#'   \item{\code{I}}{Intensity normalized by measurement time.}
#'   \item{\code{I.meas}}{Raw measured intensity counts.}
#' }
#'
#' File format detection is based on the file extension. If the
#' extension is not recognized, a warning is issued and the import
#' fails.
#'
#' @return
#' A data frame containing XRD data, or an object of class \code{xrd}
#' if \code{xrd = TRUE}.
#'
#' @author
#' Thomas Gredig
#'
#' @examples
#' fname <- xrd_sample_files("rasx")
#' d <- xrd_import(fname, xrd = TRUE)
#' plot(d)
#'
#' @seealso
#' \code{\link{plot.xrd}} for visualization of imported XRD data;
#' \code{\link{xrd_sample_files}} for accessing sample XRD data files.
#'
#' @importFrom tools file_ext
#' @importFrom cli cli_warn
#' @export
xrd_import <- function(filename, xrd = FALSE) {
  check_file_exists(filename)

  fileExtension <- tolower(tools::file_ext(filename))

  d <- switch(
    fileExtension,
    asc  = xrd_read_ASC(filename),
    ras  = xrd_read_RAS(filename),
    txt  = xrd_read_TXT(filename),
    rasx = xrd_read_RASX(filename),
    cli_warn(
      "XRD file extension ({fileExtension}) is not recognized; file cannot be imported."
    )
  )

  if (xrd) class(d) <- "xrd"
  d
}



#' @rdname xrd_import
#' @export
xrd.import <- function(filename, xrd = FALSE) {
  .Deprecated("xrd_import", package = "rigakuXRD")
  xrd_import(filename = filename, xrd = xrd)
}




#' @importFrom cli cli_abort
#' @noRd
check_file_exists <- function(filename) {
  if (!file.exists(filename)) {
    cli_abort("File {filename} does not exist.")
  }
}

#' Plot method for \code{xrd} objects
#'
#' Produces a logarithmic-intensity XRD diffraction plot from an
#' \code{xrd} S3 object. It is generally created with \code{xrd_import()}
#'
#' @param x An \code{xrd} S3 object containing \code{TwoTheta} and
#'   intensity data.
#' @param ... Additional graphical parameters passed to
#'   \code{\link[graphics]{plot}}.
#'
#' @seealso \code{\link{xrd_import}} for reading XRD data files into
#'   \code{xrd} objects using \code{xrd=TRUE}.
#'
#' @return No return value; the XRD spectrum is plotted for its side effect.
#'   The method draws a logarithmic-intensity plot from the \code{TwoTheta}
#'   and \code{I} columns and passes additional graphical arguments to
#'   \code{\link[graphics]{plot}}.
#'
#' @export
plot.xrd <- function(x, ...) {
  plot(
    x$TwoTheta,
    x$I,
    log = "y",
    col = "red",
    xlab = expression(2*theta),
    ylab = "log I (cps)",
    ...
  )
}


#' Reads the ASC Rigaku XRD file with a Header
#' @param filename filename including path
#' @return data frame with XRD data
#'
#' @importFrom stringr str_extract_all
#' @importFrom utils read.csv
#' @importFrom stats na.omit
#' @noRd
xrd_read_ASC <- function(filename) {
  check_file_exists(filename)

  data <- read.csv(file=filename, stringsAsFactors=FALSE, row.names=NULL, header=FALSE)

  # get data only
  xrd.data = read.csv(file=filename, stringsAsFactors=FALSE, row.names=NULL, comment.char = '*', header = FALSE)
  x1 = c(xrd.data$V1, xrd.data$V2, xrd.data$V3, xrd.data$V4)
  ln = nrow(xrd.data)
  # now re-arrange: 1,ln+1, 2ln+1, 3ln+1 , 2, ln+2 , ...
  x1p <- rep(1:ln, each=4)
  x1p[(1:ln)*4-2] <- x1p[(1:ln)*4-2] + ln
  x1p[(1:ln)*4-1] <- x1p[(1:ln)*4-1] + ln*2
  x1p[(1:ln)*4] <- x1p[(1:ln)*4] + ln*3
  x2 <- x1[x1p]
  na.omit(x2) -> x2

  as.vector(unlist(data))->p

  str_extract_all(p, '\\*{1}COUNT\t') -> a
  which(a=="*COUNT\t") -> q
  as.numeric(gsub("\\D", "", p[q]))  -> b

  x.start = q+1
  x.end = q+b

  str_extract_all(p, '\\*{1}START\t') -> angle
  which(angle=="*START\t") -> q

  extract_numeric <- function(p, q, seq) {
    as.numeric(unlist(strsplit(p[q], '='))[seq])
  }

  seq <- 1:(length(q)) * 2

  theta.start <- extract_numeric(p, q, seq)
  q <- q + 1
  theta.stop <- extract_numeric(p, q, seq)
  q <- q + 1
  theta.step <- extract_numeric(p, q, seq)
  q <- q + 2
  theta.speed <- extract_numeric(p, q, seq)

  norm <- theta.speed

  data <- data.frame()
  x2p <- 1
  for(num in 1:length(q)) {
    theta = seq(from=theta.start[num], to=theta.stop[num], by=theta.step[num])
    I <- x2[x2p:(x2p+length(theta)-1)]
    data <- rbind(data, cbind(TwoTheta=theta, I = I/norm[num], I.meas = I, loop=num))
    x2p <- x2p + length(theta)
  }
  data
}



#' Reads the header of an XRD ASC file
#' @param filename filename including path
#' @return data frame with XRD header
#'
#' @export
xrd_readHeader_ASC <- function(filename) {
  check_file_exists(filename)
  data = read.csv(file=filename, stringsAsFactors=FALSE, row.names=NULL, header=FALSE)

  con.File = file(filename, "r")
  hdata = readLines(con.File)
  close(con.File)
  hdata <- hdata[grep("^\\*.*\\t", hdata)]
  hdata <- gsub('\\t+','=',hdata)
  f <- strsplit(hdata,'==')
  d = data.frame(
    name = sapply(f, '[[',1),
    val = sapply(f, '[[',2)
  )
  d$name = gsub('^\\*','',d$name)
  d$name = gsub('_',' ',d$name)
  d$name = tolower(d$name)
  d$val = gsub('^.*=\\s*','',d$val)

  d
}


#' Reads the RAS Rigaku XRD data
#' @param filename filename including path
#' @return data frame with XRD data
#'
#' @importFrom utils read.csv
#' @importFrom tidyr separate_wider_delim
#'
#' @noRd
xrd_read_RAS <- function(filename) {
  check_file_exists(filename)
  data = read.csv(file=filename, stringsAsFactors=FALSE, row.names=NULL)
  p = as.vector(unlist(data))
  p = iconv(p, from = "ISO-8859-1", to = "UTF-8")

  if(p[1]!="*RAS_HEADER_START") { warning(paste("File format is not RAS:",filename))}
  p.start = grep('*RAS_INT_START',p)
  p.end = grep('*RAS_INT_END',p)
  if (length(p.start)==0L | length(p.end)==0L) { stop("RAS file data start and end not found.") }
  d1 = data.frame(
    n = p[(p.start+1):(p.end-1)],
    stringsAsFactors = FALSE
  )

  lines.comment = grep('^\\*',p)
  n = gsub('^\\*','',p[lines.comment])
  n = n[grepl(" ",n)]
  d.header = data.frame(n, stringsAsFactors = FALSE) %>%
    separate_wider_delim(n, names=c('name','value'), delim=" ", too_many="merge")
  label.x = .xrdRasHeaderValue(d.header,'DISP_TAB_NAME')
  label.y = .xrdRasHeaderValue(d.header,'DISP_TITLE_Y')
  label.units = .xrdRasHeaderValue(d.header,'DISP_UNIT_Y')

  d2 <- separate_wider_delim(d1,n, names=c(label.x,label.y,label.units),
                         delim=" ", too_many="merge")
  d3 <- lapply(d2, as.numeric)
  names(d3) <- c("TwoTheta","I","cps")

  d3$I.meas = d3$I / d3$cps
  d3$loop = 1
  d3$cps <- NULL

  as.data.frame(d3)
}




.xrdRasHeaderValue <- function(d,item='FILE_MEMO') {
  d$value[grep(item,d$name)]
}


#' Reads the TXT Rigaku XRD file with a Header
#' @param filename filename including path
#' @return data frame with XRD data
#'
#' @importFrom utils read.csv
#' @noRd
xrd_read_TXT <- function(filename) {
  check_file_exists(filename)
  data = read.csv(file=filename, stringsAsFactors=FALSE)
  as.vector(unlist(data))->p
  p[grep('^\\*',p)] -> d.header
  strsplit(gsub('^\\*','',d.header),'\t') -> p1
  secondValue <- function(x) { if(length(x)==2){x[[2]]}else{""} }
  q1 = data.frame(
    name = unlist(lapply(p1,'[[',1)),
    value = unlist(lapply(p1, secondValue))
  )
  # find column names
  p1 = p[grep('^#',p)][1]
  col.names = unlist(strsplit(gsub('^#','',p1),'='))
  # get data
  start.row = grep('^#',p)[1]+1
  if (is.na(start.row)) { d = xrd_read_TXTnoheader(filename) }
  else {
    if (length(grep('\t', p[start.row]))>0) {
      p1 = strsplit(p[start.row:length(p)],'\t')
    } else {
      # separator is space not tab
      p1 = strsplit(p[start.row:length(p)],' ')
    }
    d = data.frame(
      v1 = as.numeric(unlist(lapply(p1,'[[',1))),
      v2 = as.numeric(unlist(lapply(p1, secondValue)))
    )
    names(d) = col.names
  }

  # change column names
  names(d) = c('TwoTheta','I')
  d$I.meas = d$I
  d$loop = 1
  d
}


#' Reads the TXT Rigaku XRD file with no header
#' @param filename filename including path
#' @return data frame with XRD data and columns TwoTheta and I
#'
#' @importFrom utils read.csv
#' @noRd
xrd_read_TXTnoheader <- function(filename) {
  check_file_exists(filename)
  d = read.csv(file=filename, sep='\t', stringsAsFactors=FALSE, header=FALSE)
  if(ncol(d)!=2) cli_abort("Format of data in XRD file {filename} is not recognized.")
  names(d) = c('TwoTheta','I')
  d
}




#' Reads the RASX Rigaku XRD data
#' @param filename filename including path
#' @return data frame with XRD data
#'
#' @author Thomas Gredig
#' @importFrom utils read.csv unzip
#'
#' @noRd
xrd_read_RASX <- function(filename) {
  check_file_exists(filename)

  pTemp = tempdir()
  unzip(filename, exdir=pTemp)
  dataFile = file.path(pTemp, 'Data0', 'Profile0.txt')

  data = read.csv(file=dataFile, sep='\t', stringsAsFactors=FALSE, row.names=NULL, header=FALSE)
  names(data) = c('TwoTheta','I.meas','factor')

  conditionFile = file.path(pTemp, 'Data0', "MesurementConditions0.xml")
  rCond <- xrd.readMeasurementConditions(conditionFile)
  if (!rCond$speed_unit == "deg/min") warning(paste("Expected scanning speed in units of deg/min, but instead ",rCond$speed_unit))
  speed_secPerStep  = rCond$step_2theta / rCond$speed * 60

  data = data.frame(
    TwoTheta = data$TwoTheta,
    I = data$I.meas * data$factor / speed_secPerStep,
    I.meas = data$I.meas * data$factor,
    loop = 1L
  )
  data
}

#' Reads RASX header information
#' @param filename Character string giving the path to a RASX file.
#' @export
xrd_read_RASX_header <- function(filename) {
  check_file_exists(filename)
  if (!grepl("\\.rasx$", filename, ignore.case = TRUE)) stop("`file` must have extension `.rasx`.", call. = FALSE)
  pTemp = tempdir()
  unzip(filename, exdir=pTemp)
  conditionFile = file.path(pTemp, 'Data0', "MesurementConditions0.xml")
  r <- xrd.readMeasurementConditions(conditionFile)
  r$file = basename(filename)
  r
}


#' Reads the XML file with the conditions of the XRD measurement
#' @importFrom xml2 xml_text xml_find_first read_xml
#' @noRd
xrd.readMeasurementConditions <- function(file) {
  if (missing(file) || is.null(file) || length(file) != 1L || !nzchar(file)) {
    stop("`file` must be a single non-empty file path.", call. = FALSE)
  }

  if (!file.exists(file)) {
    stop("File does not exist: ", file, call. = FALSE)
  }

  xml <- xml2::read_xml(file)

  get_text <- function(xpath, default = NA_character_) {
    node <- xml2::xml_find_first(xml, xpath)
    if (inherits(node, "xml_missing")) return(default)

    value <- xml2::xml_text(node)
    if (is.null(value) || length(value) == 0L || !nzchar(value)) {
      return(default)
    }

    value
  }

  get_num <- function(xpath, default = NA_real_) {
    value <- get_text(xpath, default = NA_character_)
    if (is.na(value)) return(default)

    out <- suppressWarnings(as.numeric(value))
    if (is.na(out)) default else out
  }

  get_logical <- function(xpath, default = NA) {
    value <- get_text(xpath, default = NA_character_)
    if (is.na(value)) return(default)

    value <- tolower(trimws(value))

    if (value %in% c("true", "t", "1", "yes", "y")) return(TRUE)
    if (value %in% c("false", "f", "0", "no", "n")) return(FALSE)

    default
  }

  get_axis_attr <- function(axis_name, attr, default = NA_character_) {
    xpath <- sprintf(".//Axes/Axis[@Name='%s']", axis_name)
    node <- xml2::xml_find_first(xml, xpath)

    if (inherits(node, "xml_missing")) return(default)

    value <- xml2::xml_attr(node, attr)
    if (is.null(value) || length(value) == 0L || is.na(value) || !nzchar(value)) {
      return(default)
    }

    value
  }

  get_category_unit <- function(category_name, default = NA_character_) {
    xpath <- sprintf(".//HWConfigurations/Categories/Category[@Name='%s']",
                     category_name)
    node <- xml2::xml_find_first(xml, xpath)

    if (inherits(node, "xml_missing")) return(default)

    value <- xml2::xml_attr(node, "SelectedUnit")
    if (is.null(value) || length(value) == 0L || is.na(value) || !nzchar(value)) {
      return(default)
    }

    value
  }

  scan_axis <- get_text(".//ScanInformation/AxisName")

  attenuator_position <- get_axis_attr("Attenuator", "Position")
  attenuator_auto <- get_logical(".//ScanInformation/AttenuatorAutoMode")
  attenuator_unit <- get_category_unit("ReceivingAttenuator")

  attenuated <- NA
  if (!is.na(attenuator_position)) {
    attenuated <- !tolower(attenuator_position) %in% c(
      "none", "no", "off", "open", "0", ""
    )
  }

  data.frame(
    file = basename(file),

    sample_name = get_text(".//GeneralInformation/SampleName"),
    memo = get_text(".//GeneralInformation/Memo"),
    measurement_type = get_text(".//GeneralInformation/Type"),
    system_name = get_text(".//GeneralInformation/SystemName"),

    scan_axis = scan_axis,
    scan_mode = get_text(".//ScanInformation/Mode"),

    start_2theta = get_num(".//ScanInformation/Start"),
    end_2theta = get_num(".//ScanInformation/Stop"),
    step_2theta = get_num(".//ScanInformation/Step"),
    speed = get_num(".//ScanInformation/Speed"),
    speed_unit = get_text(".//ScanInformation/SpeedUnit"),
    angle_unit = get_text(".//ScanInformation/PositionUnit"),

    data_count = get_num(".//ScanInformation/DataCount"),
    intensity_unit = get_text(".//ScanInformation/IntensityUnit"),

    attenuated = attenuated,
    attenuator_position = attenuator_position,
    attenuator_auto_mode = attenuator_auto,
    attenuator_selected_unit = attenuator_unit,

    xray_target = get_text(".//HWConfigurations/XrayGenerator/TargetName"),
    xray_wavetype = get_text(".//HWConfigurations/XrayGenerator/WaveType"),
    voltage = get_num(".//HWConfigurations/XrayGenerator/Voltage"),
    voltage_unit = get_text(".//HWConfigurations/XrayGenerator/VoltageUnit"),
    current = get_num(".//HWConfigurations/XrayGenerator/Current"),
    current_unit = get_text(".//HWConfigurations/XrayGenerator/CurrentUnit"),
    wavelength_kalpha1 = get_num(".//HWConfigurations/XrayGenerator/WavelengthKalpha1"),
    wavelength_kalpha2 = get_num(".//HWConfigurations/XrayGenerator/WavelengthKalpha2"),
    wavelength_kbeta = get_num(".//HWConfigurations/XrayGenerator/WavelengthKbeta"),

    start_time = get_text(".//ScanInformation/StartTime"),
    end_time = get_text(".//ScanInformation/EndTime"),

    stringsAsFactors = FALSE
  )
}
